using LedgerFlow.Api.Models;using Microsoft.EntityFrameworkCore;namespace LedgerFlow.Api.Data;public sealed class AppDbContext(DbContextOptions<AppDbContext> options):DbContext(options){public DbSet<Transaction> Transactions=>Set<Transaction>();public DbSet<AuditEvent> AuditEvents=>Set<AuditEvent>();protected override void OnModelCreating(ModelBuilder b){b.Entity<Transaction>().HasIndex(x=>x.Reference).IsUnique();b.Entity<Transaction>().Property(x=>x.Amount).HasPrecision(18,2);b.Entity<AuditEvent>().HasIndex(x=>new{x.EntityType,x.EntityId,x.OccurredAt});}}
